mapper.select:
SELECT s.id, COALESCE(NULLIF(sm.alias_name, ''), u.username) AS name, u.avatar AS icon FROM (
SELECT ps.session_id, ps.uid2 AS peer_id FROM im_peer_session ps WHERE ps.uid1 = #{userId}
UNION ALL
SELECT ps.session_id, ps.uid1 AS peer_id FROM im_peer_session ps WHERE ps.uid2 = #{userId}
) t JOIN im_session s ON s.id = t.session_id JOIN user u ON u.id = t.peer_id LEFT JOIN im_session_member sm ON sm.session_id = t.session_id AND sm.user_id = #{userId} ORDER BY s.id DESC

select * from im_message
where session_id = #{sessionId}


        and id > #{since}


        and id < #{before}


order by id
limit #{count}

select * from im_message
where session_id = #{sessionId}

    and id < #{beforeMessageId}

order by id desc
limit #{limit}

select count(1) > 0 from im_session_member
where session_id = #{sessionId}
  and user_id = #{userId}
  and is_exit = 0
